#include "SoundAdviceLookAndFeel.h"

#if SOUNDADVICE_HAS_FONTS
 #include "FontData.h"   // generated by CMake from Resources/Fonts/
#endif

namespace
{
    const juce::Identifier fontFamilyId { "fontFamily" };
    const juce::Identifier fontHeightId { "fontHeight" };
}

SoundAdviceLookAndFeel::SoundAdviceLookAndFeel()
{
   #if SOUNDADVICE_HAS_FONTS
    for (int i = 0; i < FontData::namedResourceListSize; ++i)
    {
        int size = 0;
        auto* data = FontData::getNamedResource (FontData::namedResourceList[i], size);

        if (data == nullptr)
            continue;

        if (auto typeface = juce::Typeface::createSystemTypefaceFor (data, (size_t) size))
        {
            auto family = typeface->getName();
            auto style  = typeface->getStyle();

            // Register as "Family Style" (e.g. "Bungee Bold") and also plain
            // "Family". The first style loaded for a family wins the plain name.
            typefaces[family + " " + style] = typeface;
            typefaces.emplace (family, typeface);
        }
    }

    DBG ("Embedded fonts: " << getEmbeddedFontNames().joinIntoString (", "));
   #endif
}

void SoundAdviceLookAndFeel::useFont (juce::Component& c, const juce::String& family, float height)
{
    c.getProperties().set (fontFamilyId, family);
    c.getProperties().set (fontHeightId, height);
    c.repaint();
}

juce::Font SoundAdviceLookAndFeel::getFont (const juce::String& family, float height) const
{
    if (auto it = typefaces.find (family); it != typefaces.end())
        return juce::Font (juce::FontOptions (it->second).withHeight (height));

    // Not embedded: try a system-installed font with that name.
    return juce::Font (juce::FontOptions (family, height, juce::Font::plain));
}

juce::StringArray SoundAdviceLookAndFeel::getEmbeddedFontNames() const
{
    juce::StringArray names;
    for (auto& [name, typeface] : typefaces)
        names.add (name);
    return names;
}

juce::Font SoundAdviceLookAndFeel::getTextButtonFont (juce::TextButton& button, int buttonHeight)
{
    auto& props = button.getProperties();

    if (! props.contains (fontFamilyId))
        return LookAndFeel_V4::getTextButtonFont (button, buttonHeight);

    auto height = (float) props[fontHeightId];
    if (height <= 0.0f)
        height = juce::jmin (20.0f, (float) buttonHeight * 0.6f);

    return getFont (props[fontFamilyId].toString(), height);
}

void SoundAdviceLookAndFeel::drawButtonText (juce::Graphics& g,
                                              juce::TextButton& button,
                                              bool /*isMouseOver*/,
                                              bool /*isButtonDown*/)
{
    const auto& props = button.getProperties();
    const auto  shape = props["iconShape"].toString();

    if (shape == "play")
    {
        auto b = button.getLocalBounds().toFloat().reduced(10.0f);
        juce::Path p;
        p.addTriangle(b.getX(),       b.getY(),
                      b.getX(),       b.getBottom(),
                      b.getRight(),   b.getCentreY());
        g.setColour(juce::Colours::white);
        g.fillPath(p);
        return;
    }

    if (shape == "record")
    {
        auto b = button.getLocalBounds().toFloat().reduced(10.0f);
        g.setColour(juce::Colours::red);
        g.fillEllipse(b);
        return;
    }

    // Default text rendering.
    LookAndFeel_V4::drawButtonText(g, button, false, false);
}

juce::Font SoundAdviceLookAndFeel::getLabelFont (juce::Label& label)
{
    auto& props = label.getProperties();

    if (! props.contains (fontFamilyId))
        return LookAndFeel_V4::getLabelFont (label);

    // No explicit height: keep whatever size the label was given via setFont().
    auto height = (float) props[fontHeightId];
    if (height <= 0.0f)
        height = label.getFont().getHeight();

    return getFont (props[fontFamilyId].toString(), height);
}
